END $rpm_seed$;
SELECT setval(pg_get_serial_sequence('rpm.products','id'),COALESCE((SELECT MAX(id) FROM rpm.products),1),EXISTS(SELECT 1 FROM rpm.products));
DO $rpm_storage$ BEGIN
IF to_regclass('storage.buckets') IS NOT NULL THEN
INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types) VALUES('rpm-products','rpm-products',false,4194304,ARRAY['image/jpeg','image/png','image/webp']) ON CONFLICT(id) DO NOTHING;
END IF;
END $rpm_storage$;
COMMIT;
